#!/usr/bin/env node
/*
 * Branding code generator (P003).
 *
 * Reads branding.config.json — the single source of truth — and emits:
 *   packages/branding/src/generated.ts  (frozen typed object + CSS var names)
 *   packages/branding/src/index.ts      (typed accessor surface)
 *   crates/core-protocol/src/brand.rs   (Rust constants)
 *
 * Every output carries a DO NOT EDIT header and is committed. To change the
 * brand, edit branding.config.json (or run scripts/rename.mjs) and re-run:
 *   node scripts/branding-codegen.mjs [--root <dir>] [--check]
 * --check exits 1 when outputs are stale instead of rewriting them.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const defaultRoot = path.resolve(here, '..');

const HEADER_TS = (name) =>
  `// DO NOT EDIT — generated by scripts/branding-codegen.mjs from branding.config.json (${name}).\n// Edit the config (or run scripts/rename.mjs), then re-run: node scripts/branding-codegen.mjs\n`;
const HEADER_RS = `//! DO NOT EDIT — generated by scripts/branding-codegen.mjs from branding.config.json.\n//! Edit the config (or run scripts/rename.mjs), then re-run the generator.\n`;

function loadConfig(root) {
  return JSON.parse(readFileSync(path.join(root, 'branding.config.json'), 'utf8'));
}

function tsString(s) {
  return JSON.stringify(s);
}

export function generate(rootDir = defaultRoot, cfg = loadConfig(rootDir)) {
  const files = {};
  const css = {
    productName: `--${cfg.codeToken}-product-name`,
    codeToken: `--${cfg.codeToken}-code-token`,
    daemonBinary: `--${cfg.codeToken}-daemon-binary`,
    cliBinary: `--${cfg.codeToken}-cli-binary`,
    configDir: `--${cfg.codeToken}-config-dir`,
  };

  const generatedTs =
    HEADER_TS('generated.ts') +
    `export const BRANDING = Object.freeze({\n` +
    `  status: ${tsString(cfg.status)},\n` +
    `  codename: ${tsString(cfg.codename)},\n` +
    `  productName: ${tsString(cfg.productName)},\n` +
    `  codeToken: ${tsString(cfg.codeToken)},\n` +
    `  cliBinary: ${tsString(cfg.cliBinary)},\n` +
    `  orgHandle: ${tsString(cfg.orgHandle)},\n` +
    `  repoName: ${tsString(cfg.repoName)},\n` +
    `  daemonBinary: ${tsString(cfg.daemonBinary)},\n` +
    `  configDirName: ${tsString(cfg.configDirName)},\n` +
    `  copyrightHolder: ${tsString(cfg.copyrightHolder)},\n` +
    `  domains: Object.freeze(${JSON.stringify(cfg.domains)}),\n` +
    `  packages: Object.freeze(${JSON.stringify(cfg.packages)}),\n` +
    `  clearance: Object.freeze({\n` +
    `    trademark: ${tsString(cfg.clearance.trademark)},\n` +
    `    publishBlocked: ${String(cfg.clearance.publishBlocked)},\n` +
    `  }),\n` +
    `} as const);\n\n` +
    `export type Branding = typeof BRANDING;\n\n` +
    `export const BRAND_CSS_VARS = Object.freeze({\n` +
    Object.entries(css)
      .map(([k, v]) => `  ${k}: ${tsString(v)},`)
      .join('\n') +
    `\n} as const);\n\n` +
    `export type BrandCssVars = typeof BRAND_CSS_VARS;\n`;
  files['packages/branding/src/generated.ts'] = generatedTs;

  const indexTs =
    HEADER_TS('index.ts') +
    `import { BRANDING, BRAND_CSS_VARS } from './generated.js';\n\n` +
    `export type { Branding, BrandCssVars } from './generated.js';\n` +
    `export { BRANDING, BRAND_CSS_VARS };\n\n` +
    `/** Typed read access to the frozen brand object. */\n` +
    `export function getBrand(): Readonly<typeof BRANDING> {\n  return BRANDING;\n}\n\n` +
    `export function getProductName(): string {\n  return BRANDING.productName;\n}\n\n` +
    `export function getCodeToken(): string {\n  return BRANDING.codeToken;\n}\n\n` +
    `export function getDaemonBinary(): string {\n  return BRANDING.daemonBinary;\n}\n\n` +
    `export function getCliBinary(): string {\n  return BRANDING.cliBinary;\n}\n\n` +
    `export function getConfigDirName(): string {\n  return BRANDING.configDirName;\n}\n\n` +
    `/** Look up a generated CSS custom-property name by key. */\n` +
    `export function cssVar(name: keyof typeof BRAND_CSS_VARS): string {\n  return BRAND_CSS_VARS[name];\n}\n`;
  files['packages/branding/src/index.ts'] = indexTs;

  const str = (v) => `"${String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
  const brandRs =
    HEADER_RS +
    `pub const STATUS: &str = ${str(cfg.status)};\n` +
    `pub const CODENAME: &str = ${str(cfg.codename)};\n` +
    `pub const PRODUCT_NAME: &str = ${str(cfg.productName)};\n` +
    `pub const CODE_TOKEN: &str = ${str(cfg.codeToken)};\n` +
    `pub const CLI_BINARY: &str = ${str(cfg.cliBinary)};\n` +
    `pub const DAEMON_BINARY: &str = ${str(cfg.daemonBinary)};\n` +
    `pub const CONFIG_DIR_NAME: &str = ${str(cfg.configDirName)};\n` +
    `pub const COPYRIGHT_HOLDER: &str = ${str(cfg.copyrightHolder)};\n` +
    `pub const TRADEMARK_CLEARED: bool = ${cfg.clearance.trademark === 'CLEARED' ? 'true' : 'false'};\n` +
    `pub const PUBLISH_BLOCKED: bool = ${cfg.clearance.publishBlocked ? 'true' : 'false'};\n`;
  files['crates/core-protocol/src/brand.rs'] = brandRs;

  return files;
}

function main() {
  const args = process.argv.slice(2);
  const rootIdx = args.indexOf('--root');
  const root = rootIdx >= 0 && args[rootIdx + 1] ? path.resolve(args[rootIdx + 1]) : defaultRoot;
  const check = args.includes('--check');
  const cfg = loadConfig(root);
  const files = generate(root, cfg);
  let stale = [];
  for (const [rel, text] of Object.entries(files)) {
    const abs = path.join(root, rel);
    if (check) {
      let cur = null;
      try {
        cur = readFileSync(abs, 'utf8');
      } catch {
        cur = null;
      }
      if (cur !== text) stale.push(rel);
    } else {
      mkdirSync(path.dirname(abs), { recursive: true });
      writeFileSync(abs, text, 'utf8');
      console.log(`wrote ${rel}`);
    }
  }
  if (check) {
    if (stale.length > 0) {
      console.error(`STALE generated files:\n  - ${stale.join('\n  - ')}\nRe-run: node scripts/branding-codegen.mjs`);
      process.exitCode = 1;
    } else {
      console.log('generated files are current.');
    }
  }
}

main();
